include_class Java::org.apache.hadoop.hbase.NamespaceExistException

tenants = ARGV[1].split(',').map { |tenant| tenant.split(':') }
tenants.each do |namespace, role_account|
  # FIXME list_namespace doesn't return any data and dumps everything to the
  # $stdout. It has been tested in tests that exceptions generated by
  # created_namespace gets ignored and hbase shell will iterate through this
  # list.
  admin = @shell.hbase.admin nil
  begin
    admin.create_namespace namespace
    grant role_account, 'RWCAX', "@#{namespace}"
  rescue  NamespaceExistException
    puts "skipping already existing namespace #{namespace}. including permissions"
  end
end
